package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DcrAllowedGrantTypesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dcr allowed grant types of tenant config ")
  void test_dcr_allowed_grant_types_v_o_builder() {
    Assertions.assertFalse(DcrAllowedGrantTypesVO.nullValue().getDcrAllowedGrantTypes().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        DcrAllowedGrantTypesVO.tryFrom(null).getDcrAllowedGrantTypes().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        DcrAllowedGrantTypesVO.from("one").getDcrAllowedGrantTypes().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DcrAllowedGrantTypesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DcrAllowedGrantTypesVO.from("one").toString());
  }
}
